const query = String(input.query || '').trim();
const limit = Math.max(1, Math.min(Number(input.limit) || 8, 20));
const source = new URL('/search', location.origin);
source.searchParams.set('q', query);
source.searchParams.set('src', 'typed_query');
source.searchParams.set('f', 'live');
const loginPath = /^\/(?:i\/flow\/login|login)(?:\/|$)/.test(location.pathname);
const isVisible = element => {
  if (!element || !element.getBoundingClientRect) return false;
  if (element.hidden || (typeof element.getAttribute === 'function' && element.getAttribute('aria-hidden') === 'true')) return false;
  const rect = element.getBoundingClientRect();
  const style = typeof getComputedStyle === 'function' ? getComputedStyle(element) : null;
  return rect.width > 0 && rect.height > 0 && (!style || (style.display !== 'none' && style.visibility !== 'hidden'));
};
const hasVisibleLoginForm = () => Array.from(document.querySelectorAll('form')).some(form =>
  isVisible(form) && Array.from(form.querySelectorAll('input[autocomplete="username"], input[name="text"], input[type="password"]')).some(isVisible)
);
const hasExplicitEmptyState = () => {
  if (typeof document.querySelector !== 'function') return false;
  const element = document.querySelector('main [data-testid="emptyState"]');
  if (!isVisible(element)) return false;
  const normalizeQuotes = value => value.replace(/[“”]/g, '"').replace(/[‘’]/g, "'");
  const text = normalizeQuotes(String(element.innerText || element.textContent || '')).replace(/\s+/g, ' ').trim().toLowerCase();
  const normalizedQuery = normalizeQuotes(query).replace(/\s+/g, ' ').trim().toLowerCase();
  return !!normalizedQuery && (
    text.includes(`no results for "${normalizedQuery}"`) ||
    text.includes(`no results for '${normalizedQuery}'`) ||
    text.includes(`没有关于"${normalizedQuery}"的结果`) ||
    text.includes(`没有关于'${normalizedQuery}'的结果`)
  );
};
const sleep = ms => new Promise(resolve => setTimeout(resolve, ms));
let articles = [];
let loginForm = false;
let emptyState = false;
for (let attempt = 0; attempt < 40; attempt += 1) {
  if (loginPath) break;
  articles = Array.from(document.querySelectorAll('article'));
  if (articles.length) break;
  loginForm = hasVisibleLoginForm();
  if (loginForm) break;
  emptyState = hasExplicitEmptyState();
  if (emptyState) break;
  if (attempt < 39) await sleep(250);
}
if (loginPath || loginForm) {
  return {
    success: false,
    status: 'requires_auth',
    requiresLogin: true,
    message: 'X requires authentication to read this search timeline',
    query,
    source: source.href
  };
}
if (emptyState) {
  return { success: true, status: 'empty', query, posts: [], sources: { page: source.href } };
}
if (!articles.length) {
  return { success: false, status: 'loading_timeout', requiresLogin: false, message: 'X search articles did not become visible within 10 seconds', query, source: source.href };
}
const mainStatusLink = article => Array.from(article.querySelectorAll('a:has(time)')).find(link => {
  const href = link.getAttribute('href') || '';
  try {
    return /^\/[^/]+\/status\/\d+$/.test(new URL(href, location.origin).pathname);
  } catch {
    return false;
  }
});
const posts = articles.slice(0, limit).map(article => {
  const text = String(article.querySelector('[data-testid="tweetText"]') && article.querySelector('[data-testid="tweetText"]').innerText || '').trim();
  const nameBlock = String(article.querySelector('[data-testid="User-Name"]') && article.querySelector('[data-testid="User-Name"]').innerText || '').trim();
  const author = nameBlock.split('\n').map(part => part.trim()).find(Boolean) || '';
  const statusLink = mainStatusLink(article);
  const href = statusLink ? statusLink.getAttribute('href') || '' : '';
  const time = statusLink ? statusLink.querySelector('time') : null;
  return {
    text,
    author,
    url: href ? new URL(href, location.origin).href : '',
    publishedAt: time ? String(time.getAttribute('datetime') || '') : ''
  };
}).filter(post => post.text && post.url);
if (!posts.length) {
  return { success: false, status: 'unreadable', requiresLogin: false, message: 'Visible X articles did not expose readable text and main status links', query, source: source.href };
}
return { success: true, status: 'ok', query, posts, sources: { page: source.href } };
